INSERT INTO feature VALUES('theory-include','descriptions','Theory inclusion','signature-models','partial','notable',NULL,'A theory includes another as a function on Theory values with the morphism kept, its parts included or restricted by name; the union''s critical pairs are refused by name, and a member the including block refuses where the included one reads it is refused at the `include`, in the including block. An include names a theory its own source reads before it, or else the one a source it imports unqualified presents, two such sources refused by name; a block that gives two theories it reaches a second join among the theories it sees is refused, the pair and both joins named. A model type fixes a sort by `with sort x = A` (gandr #1306). A theory `T` takes a reduct `T.S` for each theory `S` it includes, directly or through another, the ways round a diamond one reduct: it restricts a model of `T` to the model of `S` the same module gives, by computation, and a model of `T` stands where a model of `S` is asked, the checker applying the reduct there. The explicit form writes the applied reduct as its call, `T.S(m)`; the sugared form leaves a written call to the checker where it would apply the reduct; the printer writing it and hover naming it are the next rungs.','theory-levitation surface-lowering surface-grammar core-checker core-term surface-format surface-dispatcher','corpus/model/include/monoid.gandr corpus/model/include/imported.gandr corpus/model/include/reduct.gandr corpus/model/include/reduct-explicit.gandr corpus/pathological/include/rules-join.gandr corpus/pathological/include/imported-rules.gandr corpus/pathological/include/two-joins.gandr corpus/pathological/specification/specification-monad.gandr crates/surface-lowering/tests/namespace.rs crates/surface-lowering/tests/modules/models.rs crates/core-checker-base/src/module/tests.rs crates/core-checker-base/tests/module.rs crates/surface-dispatcher/src/format.rs','corpus/ledger/features/theory-include.gandr','#1092 #2714');
